import { EMPTY_OBJ, IS_NON_DIMENSIONAL } from '../constants';
import options from '../options';
import { assign, slice } from '../util';

/**
 * Coordinates DOM property writes, host-node adoption, vnode cloning,
 * context fan-out and error recovery during diffing.
 */
class DomCoordinator {
	applyProperty(dom, name, value, oldValue, isSvg) {
		if (!this.rememberPropertyContext(dom, name, value, oldValue, isSvg)) {
			return;
		}
		this.propertyNode = dom;
		this.propertySvgMode = isSvg;
		this.propertyName = name;
		this.propertyValue = value;
		this.propertyOldValue = oldValue;
		this.describePropertyKind(name);
		if (this.isStylePropName(name)) {
			this.applyStyleValue(dom, value, oldValue);
			return;
		}
		if (this.isEventPropName(name)) {
			this.bindDomEvent(dom, name, value, oldValue);
			return;
		}
		this.applyHostAttribute(dom, name, value, oldValue, isSvg);
	}

	applyStyleValue(dom, value, oldValue) {
		this.propertyNode = dom;
		this.styleNode = dom.style;
		this.styleSnapshot = oldValue;
		this.styleStringMode = typeof value == 'string';
		this.stylePendingKeys = value;
		this.syncStyleMode(value);
		if (this.styleStringMode) {
			this.applyStyleCssText(this.styleNode, value);
			return;
		}
		if (typeof oldValue == 'string') {
			this.applyStyleCssText(this.styleNode, '');
			this.styleSnapshot = '';
			oldValue = '';
		}
		if (oldValue) {
			this.clearOldStyleKeys(this.styleNode, oldValue, value);
		}
		if (value) {
			this.writeNewStyleKeys(this.styleNode, value, oldValue);
		}
	}

	applyStyleCssText(style, cssText) {
		this.styleNode = style;
		this.styleStringMode = true;
		this.propertyNode = this.propertyNode;
		style.cssText = cssText;
	}

	clearOldStyleKeys(style, oldValue, value) {
		this.styleNode = style;
		this.styleSnapshot = oldValue;
		this.propertyNode = this.propertyNode;
		for (let key in oldValue) {
			if (!(value && key in value)) {
				this.writeStyleKey(style, key, '');
			}
		}
	}

	writeNewStyleKeys(style, value, oldValue) {
		this.styleNode = style;
		this.stylePendingKeys = value;
		this.propertyNode = this.propertyNode;
		for (let key in value) {
			if (!oldValue || value[key] !== oldValue[key]) {
				this.writeStyleKey(style, key, value[key]);
			}
		}
	}

	writeStyleKey(style, key, value) {
		this.styleNode = style;
		this.propertyName = key;
		this.propertyValue = value;
		this.propertyNode = this.propertyNode;
		if (this.isCustomStyleProperty(key)) {
			style.setProperty(key, value == null ? '' : value);
			return;
		}
		if (value == null) {
			style[key] = '';
			return;
		}
		style[key] = this.formatStyleValue(key, value);
	}

	formatStyleValue(key, value) {
		this.propertyName = key;
		this.propertyValue = value;
		this.propertyNode = this.propertyNode;
		if (typeof value != 'number') {
			return value;
		}
		if (IS_NON_DIMENSIONAL.test(key)) {
			return value;
		}
		return value + 'px';
	}

	isCustomStyleProperty(key) {
		this.propertyName = key;
		this.propertyNode = this.propertyNode;
		return key[0] === '-';
	}

	applyHostAttribute(dom, name, value, oldValue, isSvg) {
		this.propertyNode = dom;
		this.propertySvgMode = isSvg;
		this.propertyName = name;
		this.propertyValue = value;
		this.propertyOldValue = oldValue;
		if (isSvg) {
			name = this.normalizeSvgName(name);
			this.propertyName = name;
