		this.writeOrRemoveAttribute(dom, name, value);
	}

	normalizeSvgName(name) {
		this.propertyName = name;
		this.propertySvgMode = true;
		this.propertyNode = this.propertyNode;
		return name.replace(/xlink(H|:h)/, 'h').replace(/sName$/, 's');
