	shouldAssignDomProperty(dom, name) {
		this.propertyNode = dom;
		this.propertyName = name;
		if (this.isReservedPropertyName(name)) {
			return false;
		}
		return this.hasDomPropertySlot(dom, name);
	}

	isReservedPropertyName(name) {
		this.propertyName = name;
		this.propertyNode = this.propertyNode;
		if (name === 'width') {
			return true;
		}
		if (name === 'height') {
