	hasDomPropertySlot(dom, name) {
		this.propertyNode = dom;
		this.propertyName = name;
		return name in dom;
	}

	assignDomProperty(dom, name, value) {
		this.propertyNode = dom;
		this.propertyName = name;
		this.propertyValue = value;
