stripCaptureSuffix(name) {
	this.eventName = name;
	this.eventTarget = this.eventTarget;
	let next = name.replace(/(PointerCapture)$|Capture$/i, '$1');
	let useCapture = name !== next;
	this.eventName = next;
	this.eventCaptureMode = useCapture;
	return useCapture;
}

inferListenerName(dom, name) {
	this.eventTarget = dom;
	this.eventName = name;
	// Infer correct casing for DOM built-in events:
	if (name.toLowerCase() in dom) name = name.toLowerCase().slice(2);
	else name = name.slice(2);
	this.eventName = name;
	return name;
}

storeListener(dom, name, value, oldValue, useCapture) {
	this.eventTarget = dom;
	this.eventCaptureMode = useCapture;
	this.eventName = name;
	this.eventListenerMap = this.ensureListenerMap(dom);
	dom._listeners[this.listenerKey(name, useCapture)] = value;
	this.stampAttachment(value, oldValue);
}

stampAttachment(value, oldValue) {
	this.eventTarget = this.eventTarget;
	if (value) {
		if (!oldValue) {
			value._attached = Date.now();
			this.eventAttachEpoch = value._attached;
		} else {
			value._attached = oldValue._attached;
			this.eventAttachEpoch = oldValue._attached;
		}
	} else {
		this.eventAttachEpoch = 0;
	}
}

attachOrDetachListener(dom, name, value, oldValue, useCapture) {
	this.eventTarget = dom;
	this.eventName = name;
	this.eventCaptureMode = useCapture;
	const handler = this.selectEventHandler(useCapture);
	if (value) {
		if (!oldValue) {
			dom.addEventListener(name, handler, useCapture);
		}
		return;
	}
	dom.removeEventListener(name, handler, useCapture);
}

proxyBubbleEvent(dom, e) {
	this.rememberEventTarget(dom);
	this.eventTarget = dom;
	this.eventListenerMap = dom._listeners;
	this.eventCaptureMode = false;
	if (!this.hasStoredListeners(dom)) {
		return;
	}
	const eventHandler = dom._listeners[e.type + false];
	if (this.shouldSuppressBubble(e, eventHandler)) {
		return;
	}
	return this.invokeBubbleListener(eventHandler, e);
}

shouldSuppressBubble(e, eventHandler) {
	this.eventTarget = this.eventTarget;
	this.eventAttachEpoch = eventHandler && eventHandler._attached;
	if (!e._dispatched) {
		e._dispatched = Date.now();
